const datasets = $('02 - Cargar Datasets').item.json.datasets;
const correo = $input.first().json.bandejacorreotextoinformacion;
const tipoMovimiento = $input.first().json.tipoMovimiento;

const systemPrompt = `Eres un extractor de datos financieros para un sistema de finanzas personales en Chile.

Tu tarea es extraer informacion estructurada de un correo bancario.

El tipo de movimiento ya fue identificado como: ${tipoMovimiento}

CONTEXTO - Catalogos disponibles:
- Categorias de ingreso: ${JSON.stringify(datasets.categorias_ingreso)}
- Categorias de egreso: ${JSON.stringify(datasets.categorias_egreso)}
- Subcategorias de egreso: ${JSON.stringify(datasets.subcategorias_egreso)}
- Controlabilidad: ${JSON.stringify(datasets.controlabilidad)}
- Recurrencia: ${JSON.stringify(datasets.recurrencia)}
- Canales: ${JSON.stringify(datasets.canal)}
- Direcciones de transferencia: ${JSON.stringify(datasets.direccion_transferencia)}
- Contrapartes conocidas: ${JSON.stringify(datasets.contrapartes)}
- Bancos: ${JSON.stringify(datasets.bancos)}
- Divisas: ${JSON.stringify(datasets.divisas)}

Responde SIEMPRE en JSON con esta estructura:
{
  "tipo": "${tipoMovimiento}",
  "contraparte": "nombre del comercio o persona",
  "monto": 12345,
  "divisa": "CLP",
  "fechaMovimiento": "YYYY-MM-DD",
  "descripcion": "breve descripcion del movimiento",
  "cuenta": "numero o tipo de cuenta",
  "tarjeta": "ultimos 4 digitos",
  "tarjetaProveedor": "Visa|Mastercard",
  "esInformadoPorBanco": true,
  "categoriaIngreso": "nombre exacto de la lista de categorias de ingreso",
  "categoriaEgreso": "nombre exacto de la lista de categorias de egreso",
  "subcategoriaEgreso": "nombre exacto de la lista de subcategorias",
  "controlabilidad": "nombre exacto de la lista",
  "recurrencia": "nombre exacto de la lista",
  "canal": "nombre exacto de la lista",
  "direccionTransferencia": "Entrante|Saliente",
  "banco": "nombre exacto de la lista de bancos",
  "esCuotas": false,
  "numeroCuotaActual": null,
  "totalCuotas": null,
  "esCargoAutomatico": false
}

Reglas:
- SIEMPRE usa los nombres exactos de los catalogos proporcionados. No inventes categorias.
- monto debe ser un numero positivo (sin signos, sin puntos de miles).
- Si el monto esta en dolares, indica divisa='USD' y monto en dolares.
- fechaMovimiento en formato YYYY-MM-DD (si no esta disponible, usa la fecha del correo).
- Para transferencias: incluye direccionTransferencia ('Entrante' si recibes, 'Saliente' si envias).
- Para compras en cuotas: esCuotas=true, numeroCuotaActual y totalCuotas.`;

return [{
  json: { systemPrompt, userPrompt: correo, tipoMovimiento }
}];

const raw = $input.first().json;
let mov;

try {
  if (typeof raw.message === 'string') {
    mov = JSON.parse(raw.message);
  } else if (raw.message && raw.message.content) {
    mov = JSON.parse(raw.message.content);
  } else if (raw.text) {
    mov = JSON.parse(raw.text);
  } else {
    mov = raw;
  }
} catch (e) {
  return [{ json: { valid: false, error: 'JSON invalido: ' + e.message } }];
}

const tipo = mov.tipo;
if (!['ingreso', 'egreso', 'transferencia'].includes(tipo)) {
  return [{ json: { valid: false, error: 'tipo invalido: ' + tipo } }];
}
if (!mov.contraparte) {
  return [{ json: { valid: false, error: 'contraparte faltante' } }];
}
if (typeof mov.monto !== 'number' || mov.monto <= 0) {
  return [{ json: { valid: false, error: 'monto invalido: ' + mov.monto } }];
}
if (!mov.divisa || !['CLP', 'USD', 'ARS', 'EUR'].includes(mov.divisa)) {
  return [{ json: { valid: false, error: 'divisa invalida: ' + mov.divisa } }];
}
if (!mov.fechaMovimiento) {
  return [{ json: { valid: false, error: 'fechaMovimiento faltante' } }];
}
if (tipo === 'egreso' && !mov.categoriaEgreso) {
  return [{ json: { valid: false, error: 'categoriaEgreso faltante' } }];
}
if (tipo === 'ingreso' && !mov.categoriaIngreso) {
  return [{ json: { valid: false, error: 'categoriaIngreso faltante' } }];
}
if (tipo === 'transferencia' && !mov.direccionTransferencia) {
  return [{ json: { valid: false, error: 'direccionTransferencia faltante' } }];
}

mov.valid = true;
return [{ json: mov }];
